function page(url,title,body,desc,robots='index,follow'){
const orderParams=new URLSearchParams();
const city=cities.find(c=>url===`/locations/${slug(c)}/`);
if(city) orderParams.set('location',city);
if(url==='/professionals/')orderParams.set('type','Professional');
if(url.includes('installation'))orderParams.set('scope','Supply & installation');
if(url.includes('kitchen-design')||url.includes('custom-kitchen'))orderParams.set('help','Design my kitchen');
const collection=collections.find(c=>url===`/chicago-kitchen-cabinets/collections/${c.id}/`);
if(collection)orderParams.set('collection',collection.id);
const orderUrl='/start-order/'+(orderParams.size?'?'+orderParams.toString():'');
const actionLabel=city?`Request cabinets for ${city}`:url==='/professionals/'?'Request a project quote':url.includes('installation')?'Request cabinets & installation':url.includes('/resources/')||url.includes('/comparisons/')?'Get a quote for my kitchen':'Build your cabinet plan';
const introCopy=city?'Tell us about your kitchen. Your location carries into the request.':url==='/professionals/'?'Share your project needs and request a cabinet quote.':'Choose cabinet components and request a personalized quote.';
body=body.replace('<!--ORDER_GATEWAY-->',url==='/start-order/'||url==='/privacy/'||url==='/kitchen-survey/'||url==='/quote-confirmation/'?'':`<div class="page-order-action"><a class="btn" href="${orderUrl}">${actionLabel}</a><p>${introCopy}<br><small>No measurements or payment needed to begin.</small></p></div>`);

if(url==='/')body=homePage();
if(url==='/start-order/')body=head('Build your cabinet plan','Make room for your ideas.','Select your cabinets, personalize each one, then review a combined quote request.')+configureShell();
const dir=path.join(out,url);fs.mkdirSync(dir,{recursive:true});const webpage={"@context":"https://schema.org","@type":"WebPage",name:title,url:origin+url,description:desc||title};const business={"@context":"https://schema.org","@type":"LocalBusiness","@id":origin+"/#business",name:"Amber Leaf",url:origin,telephone:"+17732478282",email:showroom.email,address:{"@type":"PostalAddress",streetAddress:showroom.address,addressLocality:showroom.city,addressRegion:"IL",postalCode:showroom.zip,addressCountry:"US"},openingHoursSpecification:[{"@type":"OpeningHoursSpecification",dayOfWeek:["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"],opens:"09:00",closes:"18:00"}],hasMap:directions};const metadata=(url==='/'||url==='/showroom/')?[webpage,business]:webpage;fs.writeFileSync(path.join(dir,'index.html'),`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(title)} | Amber Leaf</title><meta name="description" content="${esc(desc||title)}"><meta name="robots" content="${robots}"><link rel="canonical" href="${origin}${url}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/site.css"><link rel="stylesheet" href="/commerce.css"><script type="application/ld+json">${JSON.stringify(metadata)}</script><script src="/data.js" defer></script><script src="/site.js" defer></script><script type="module" src="/commerce.js"></script></head><body>${header}<main id="main">${body}</main>${footer}</body></html>`);routes.push({url,title,robots});}
const routes=[];
function head(eyebrow,title,description,parent){return `<div class="wrap page-head"><div class="breadcrumb"><a href="/">Home</a>${parent?` / <a href="${parent[1]}">${parent[0]}</a>`:''} / ${esc(title.replace(/<br\s*\/?\s*>/g,' '))}</div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}<!--ORDER_GATEWAY--></div>`;}
function materialPhotos(c){const samples=c.id==='natural-oak'?[['Natural oak','Oak door grain',88,29],['Charcoal matte','Island finish',68,75]]:c.id==='olive-modern'?[['Charcoal matte','Slab door finish',66,24],['Warm stone','Worktop inspiration',58,43]]:[['Soft white paint','Shaker door finish',77,28],['Light stone','Worktop inspiration',55,58]];return `<aside class="material-photos" aria-label="Materials pictured"><span class="eyebrow">Materials in this look</span><div class="material-photo-grid">${samples.map(([name,detail,x,y])=>`<figure><div class="material-crop"><img src="/assets/${c.image}" alt="${name} detail from the ${c.name} design image" style="left:${50-x*6}%;top:${50-y*4}%" loading="lazy"></div><figcaption><strong>${name}</strong><span>${detail}</span></figcaption></figure>`).join('')}</div><p class="caption">Close-ups from the design image. Illustrative finishes; confirm physical samples in our showroom.</p></aside>`;}
function designSpecs(c){return `<aside class="design-specs" aria-label="${c.name} design details"><span class="design-specs-title">Sample design details <span class="mock-label">Mock example</span></span><dl><div><dt>Materials</dt><dd>Doors: ${esc(c.doorMaterial||"To be confirmed")}<br>Cabinet boxes: ${esc(c.boxMaterial||"To be confirmed")}</dd></div><div><dt>Cabinet style</dt><dd>${c.style=== "Modern" ? "Modern slab" : c.style}<small>${c.finish} finish inspiration</small></dd></div><div><dt>Approximate cabinet price</dt><dd>${esc(c.priceEstimate||"Estimate pending")}<small>${esc(c.priceScope||"Price and installation scope to be confirmed")}</small></dd></div><div><dt>Room size</dt><dd>${esc(c.roomDimensions||"Measurements pending")}<small>${c.roomArea ? c.roomArea+" · assumed room dimensions" : "Image is not a measured floor plan"}</small></dd></div></dl><p class="design-specs-note">Illustrative materials, dimensions and budget—not verified Amber Leaf specifications or a quote. Excludes installation, countertops, appliances, decorative hardware, delivery and tax.</p></aside>`;}
function card(c){return `<article class="card" data-collection="${c.id}"><div class="card-image"><a href="/chicago-kitchen-cabinets/collections/${c.id}/"><img src="/assets/${c.image}" alt="${c.name} illustrative kitchen, full-room view" loading="lazy" data-gallery-image></a><button class="save" aria-label="Save ${c.name}" aria-pressed="false" data-save="${c.id}">♡</button><button class="image-control prev" aria-label="Previous view of ${c.name}" data-gallery="-1">‹</button><span class="image-counter" aria-live="polite">1 / 3</span><button class="image-control next" aria-label="Next view of ${c.name}" data-gallery="1">›</button></div><div class="card-meta"><div><a href="/chicago-kitchen-cabinets/collections/${c.id}/"><h3>${c.name}</h3></a><p>${c.subtitle}</p></div><span class="tag">Design study</span></div><div class="card-order-action"><a class="btn outline" href="/start-order/?collection=${c.id}">Request this look</a></div></article>`;}
function floorplan(type){const pieces=type==='Compact'?[['x',35,40,50,35],['x',85,40,50,35],['x',185,40,50,35],['x',35,110,50,35],['x',85,110,50,35]]:type==='Medium'?Array.from({length:12},(_,i)=>['x',i<7?25+i*35:25,i<7?30:65+(i-7)*20,i<7?35:40,i<7?32:20]):Array.from({length:12},(_,i)=>['x',i<8?15+i*32:95+(i-8)*30,i<8?30:105,i<8?32:30,i<8?32:35]);return `<svg viewBox="0 0 290 175" role="img" aria-label="${type} example cabinet plan, schematic only"><path d="M12 15H278V158H12Z" fill="none" stroke="#919781" stroke-width="1"/>${pieces.map(([,x,y,w,h])=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#d9dccd" stroke="#626b4f"/><path d="M${x+5} ${y+h/2}h${w-10}" stroke="#626b4f" stroke-width=".7"/>`).join('')}<text x="145" y="168" text-anchor="middle" font-family="sans-serif" font-size="10" fill="#666b61">Illustrative layout · not to scale</text></svg>`;}
function packageCard(type,count,copy){return `<article class="package"><span class="tag">${count}</span>${floorplan(type)}<h3>${type} kitchen</h3><p>${copy}</p><a class="textlink" href="/start-order/?layout=${type}">Start with this layout</a></article>`;}
const hotspot=`<div class="split-image annotated"><img src="/assets/finish-natural-oak-room-v2.png" alt="Illustrative kitchen with natural oak framed doors and an natural oak island" loading="lazy"><button class="hotspot" style="left:82%;top:35%" data-hotspot="doors" aria-label="Explore the oak door finish" aria-expanded="false" aria-controls="image-info"></button><button class="hotspot" style="left:67%;top:57%" data-hotspot="drawers" aria-label="Explore drawer storage" aria-expanded="false" aria-controls="image-info"></button><button class="hotspot" style="left:45%;top:74%" data-hotspot="island" aria-label="Explore the contrasting island" aria-expanded="false" aria-controls="image-info"></button><div class="hotspot-panel" id="image-info" hidden><button class="close" aria-label="Close detail">×</button><h3></h3><p></p><a class="textlink" href="/start-order/">Add this idea to your plan</a></div></div>`;
page('/','Kitchen Cabinets in Chicago',`<section class="hero lifestyle-hero"><div class="hero-slides" aria-label="Kitchen design views"><img class="hero-slide is-active" src="/assets/layout-l.png" alt="L-shaped oak and warm white kitchen, wide room view"><img class="hero-slide" src="/assets/banner-compact-ivory.png" alt="Compact L-shaped apartment kitchen with Warm Ivory cabinets" loading="lazy"><img class="hero-slide" src="/assets/layout-galley.png" alt="Galley oak and warm white kitchen, view along parallel cabinet runs" loading="lazy"></div><div class="hero-content"><span class="eyebrow">Factory-direct cabinetry · Chicago</span><h1>The cabinets you need.<br>The colors you love.</h1><p>Factory-direct pricing, a wide range of cabinet sizes, and the colors you’re looking for—all with functional storage in one place. Need a specific size or color? Let’s plan it together.</p><div class="inline-actions"><a class="btn" href="/start-order/">Start your online order</a><a class="textlink" href="/kitchen-survey/">Tell us about your kitchen</a></div><div class="hero-proof"><div><strong>250+ projects</strong><span>Completed projects · sample figure</span></div><div><strong>4–6 weeks</strong><span>Estimated shipping · sample timeline</span></div></div><p class="hero-disclosure">Mock-up figures. Confirm our project total and your order’s shipping schedule with the team.</p></div><div class="lifestyle-controls hero-slide-controls"><button type="button" data-hero-prev aria-label="Previous kitchen view">←</button><div class="hero-slide-dots" role="group" aria-label="Choose kitchen view"><button type="button" data-hero-slide="0" aria-label="Show L-shaped kitchen" aria-pressed="true"></button><button type="button" data-hero-slide="1" aria-label="Show U-shaped kitchen" aria-pressed="false"></button><button type="button" data-hero-slide="2" aria-label="Show Galley kitchen" aria-pressed="false"></button></div><span id="hero-slide-caption" aria-live="polite">L-shaped · 1 / 3</span><button type="button" data-hero-next aria-label="Next kitchen view">→</button><button type="button" id="hero-slide-play" aria-pressed="false">Pause slideshow</button></div></section><div class="welcome"><p><strong>Your ideas are welcome here.</strong> Homeowners, designers, contractors and developers—visit our Chicago showroom.</p><a class="textlink" href="/showroom/">Explore the showroom</a></div><section class="section wrap"><div class="section-head"><div><span class="eyebrow">A kitchen that feels like you</span><h2>Start with what<br>speaks to you.</h2></div><p>Find your starting point in a color, a texture or a familiar shape. Then make room for your own ideas.</p></div><div class="tabs" role="tablist" aria-label="Browse inspiration"><button role="tab" aria-selected="true" data-browse="all">All collections</button><button role="tab" aria-selected="false" data-browse="Natural Oak">Natural wood</button><button role="tab" aria-selected="false" data-browse="Charcoal Gray">Earthy colors</button><button role="tab" aria-selected="false" data-browse="Soft White">Everyday classics</button></div><div class="grid3" id="home-collections" role="tabpanel" aria-label="Collection inspiration">${collections.map(card).join('')}</div><div class="inline-actions"><a class="textlink" href="/chicago-kitchen-cabinets/">Browse by style, color & material</a></div></section><section class="section wrap"><div class="section-head"><div><span class="eyebrow">Room to imagine</span><h2>Big ideas.<br>Your kind of space.</h2></div><p>Start with an example that feels close to your kitchen. We’ll help you capture the layout, finishes and storage you have in mind.</p></div><div class="grid3">${packageCard('Compact','5-cabinet example','A thoughtful starting point for a smaller kitchen.')}${packageCard('Medium','12-cabinet example','More room for preparation, gathering and storage.')}${packageCard('Large','A tailored layout','Perimeter cabinetry, an island and room to grow.')}</div><p class="caption">Cabinet counts describe sample packages. Actual fit depends on dimensions, appliances, openings and clearances.</p></section><section class="section dark-section"><div class="wrap split"><div class="split-copy"><span class="eyebrow">A partner in the bigger picture</span><h2>From one home<br>to a whole community.</h2><p>We collaborate with general contractors and developers on projects ranging from 5 to 5,000 units—with a commitment to sustainability, community partnerships and good design.</p><div class="inline-actions"><a class="btn" href="/professionals/">For contractors & developers</a><a class="textlink" href="/sustainability/">Our commitments</a></div></div><div class="split-image"><img src="/assets/color-charcoal-gray.png" alt="Modern olive kitchen design inspiration" loading="lazy"></div></div></section><section class="section wrap"><div class="section-head"><div><span class="eyebrow">Choose with confidence</span><h2>A clearer way<br>to compare cabinets.</h2></div><p>Compare construction, customization and the complete project scope. Find the option that fits your priorities.</p></div><div class="grid3">${comparisons.slice(0,3).map(([t,s])=>`<article class="editorial-card"><span class="eyebrow">Cabinet comparisons</span><h3>${t}</h3><p>Know which details to check before comparing quotes.</p><a class="textlink" href="/projects/comparisons/${s}/">Read the comparison</a></article>`).join('')}</div><a class="textlink" href="/projects/#comparisons">Explore all comparisons</a></section><section class="section showroom" id="showroom"><div class="wrap split"><div class="split-copy"><span class="eyebrow">Our Chicago showroom</span><h2>Come in.<br>Get inspired.<br>Everyone is welcome.</h2><p>Just gathering ideas? Planning a family kitchen? Specifying your next development? We'd love to welcome you.</p><p>See finishes up close, explore cabinet details and talk through what you have in mind.</p><p><strong>1201 W 36th Pl, Chicago, IL 60609</strong><br>Monday–Saturday, 9:00 AM–6:00 PM · Sunday: Closed</p><div class="inline-actions"><a class="btn" href="${directions}" target="_blank" rel="noopener">Get showroom directions</a><a class="textlink" href="/showroom/">Plan your showroom visit</a></div></div><div class="split-image"><img src="/assets/finish-soft-white-room-v2.png" alt="Soft white Shaker kitchen, illustrative design inspiration" loading="lazy"><p class="caption">Kitchen design inspiration; not a photograph of the showroom.</p></div></div></section><section class="section wrap"><div class="section-head"><div><span class="eyebrow">Make a thoughtful start</span><h2>From first idea<br>to a considered plan.</h2></div><a class="textlink" href="/start-order/">Start my cabinet order</a></div><div class="steps">${[['01','Find your style','Explore colors, door profiles and the details you love.'],['02','Understand your space','Start with a sample layout, then record dimensions.'],['03','Bring it together','Save your preferences in a clear project plan.'],['04','Review the details','Confirm specifications, scope and pricing with the team.']].map(([n,t,p])=>`<div><span class="num">${n}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></section><section class="section" style="background:var(--cream)"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Guides for good decisions</span><h2>A little knowledge.<br>A lot more confidence.</h2></div><a class="textlink" href="/resources/">All resources</a></div><div class="grid3">${guides.filter((_,i)=>i===0||i===2||i===3).map(([t,s,d,c])=>`<article class="editorial-card"><span class="eyebrow">${c}</span><h3>${t}</h3><p>${d}</p><a class="textlink" href="/resources/${s}/">Read the guide</a></article>`).join('')}</div></div></section>`,'Explore thoughtful kitchen cabinetry for homes and developments. Everyone is welcome at our Chicago showroom.');
page('/chicago-kitchen-cabinets/','Chicago Kitchen Cabinets',`${head('Find your starting point','Cabinets with character.','Explore by style, finish and material. Save what speaks to you, then start a plan around your space.')}<section class="wrap" style="padding-bottom:80px"><div class="filters"><label class="visually-hidden" for="filter-style">Style</label><select id="filter-style"><option value="">All styles</option><option>Shaker</option><option>Modern</option></select><label class="visually-hidden" for="filter-color">Color</label><select id="filter-color"><option value="">All colors</option><option>Natural Oak</option><option>Charcoal Gray</option><option>Soft White</option><option>Warm Ivory</option></select><label class="visually-hidden" for="filter-material">Material</label><select id="filter-material"><option value="">All materials</option><option>Oak</option><option>Painted</option></select><label class="visually-hidden" for="filter-saved">Saved collections</label><select id="filter-saved"><option value="">All collections</option><option value="saved">My saved collections</option></select><button id="clear-filters">Clear filters</button></div><div class="results-label" role="status" id="result-count">4 collections</div><div class="grid3" id="catalog-grid">${collections.map(card).join('')}</div><p class="caption">Illustrative collection concepts. Confirm available products, materials and pricing with Amber Leaf.</p><div class="inline-actions"><a class="btn" href="/start-order/">Start my cabinet order</a><a class="textlink" href="/showroom/">See finishes in person</a></div></section>${colorShowcase()}<section class="section" style="background:var(--cream)"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Fit matters</span><h2>Find your kitchen scale.</h2></div><p>Package examples help you get started. A final cabinet schedule needs actual measurements.</p></div><div class="grid3">${packageCard('Compact','5-cabinet example','Start small, with considered storage.')}${packageCard('Medium','12-cabinet example','Balance preparation and storage.')}${packageCard('Large','Tailored plan','Bring together perimeter and island storage.')}</div></div></section><section class="section wrap"><span class="eyebrow">How Amber Leaf compares</span><h2>Choose the right fit<br>for your project.</h2><div class="grid3"><div class="editorial-card"><h3>Design fit</h3><p>Compare door profiles, finish choices, available dimensions and how modifications are handled.</p></div><div class="editorial-card"><h3>Complete scope</h3><p>Separate the cabinet price from delivery, assembly, accessories and installation.</p></div><div class="editorial-card"><h3>Project support</h3><p>Consider the design review, coordination and documentation your project needs.</p></div></div><a class="textlink" href="/projects/#comparisons">Compare cabinet options</a></section>`,'Explore Chicago kitchen cabinet inspiration by style, color and material. Start a cabinet plan or visit our showroom.');
for(const c of collections){page(`/chicago-kitchen-cabinets/collections/${c.id}/`,c.name,`<div class="wrap page-head"><div class="breadcrumb"><a href="/">Home</a> / <a href="/chicago-kitchen-cabinets/">Cabinets</a> / ${c.name}</div><div class="collection-hero"><div class="card collection-design" data-collection="${c.id}"><div class="card-image"><img src="/assets/${c.image}" alt="${c.name} illustrative full-room kitchen" data-gallery-image><button class="image-control prev" data-gallery="-1" aria-label="Previous view">‹</button><span class="image-counter" aria-live="polite">1 / 3</span><button class="image-control next" data-gallery="1" aria-label="Next view">›</button></div><p class="caption">Illustrative design study · full room and cropped detail views</p></div><div><span class="eyebrow">${c.style} · ${c.color}</span><h1>${c.name}</h1><p>${c.description}</p><span class="chip">${c.finish}</span><span class="chip">${c.style} door inspiration</span><div class="inline-actions"><a class="btn" href="/start-order/?collection=${c.id}">Request this kitchen look</a><button class="btn outline" data-save="${c.id}" aria-pressed="false">Save collection</button></div><p class="caption">Request a project-specific quote. Finish and construction depend on the selected product.</p></div></div><div class="collection-details-row">${designSpecs(c)}${materialPhotos(c)}</div><div class="grid2"><div><span class="eyebrow">Bring it into your home</span><h2 style="font-size:40px">A palette to build on.</h2><p>View physical samples alongside your flooring, worktop and wall colors. Record the door profile and finish you prefer in your plan.</p><a class="textlink" href="/showroom/">Visit the Chicago showroom</a></div><div><h3>What to confirm before ordering</h3><ul class="feature-list"><li>Door and cabinet-box materials</li><li>Exact width, height and depth</li><li>Hardware and storage accessories</li><li>Finish sample and maintenance needs</li><li>Price, lead time and installation scope</li></ul><a class="textlink" href="/resources/cabinet-materials-guide/">Understand cabinet materials</a></div></div></div><section class="section" style="background:var(--cream)"><div class="wrap"><div class="section-head"><h2>Another way to see it.</h2><a class="textlink" href="/chicago-kitchen-cabinets/">All collections</a></div><div class="grid2">${collections.filter(x=>x.id!==c.id).map(card).join('')}</div></div></section>`,`${c.name} kitchen design inspiration. Explore the finish, door profile and details, then create a cabinet plan.`);}
page('/services/','Cabinet Services in Chicago',`${head('Plan. Design. Bring it together.','Support for your next kitchen.','Start with the part of your project you want to understand. Explore scope, planning and the questions to bring to a design conversation.')}<section class="wrap grid3" style="padding-bottom:80px">${services.map(([t,k,d])=>`<article class="editorial-card"><h3>${t.replace('Kitchen Cabinets ','').replace('Kitchen Cabinet ','')}</h3><p>${d}</p><a class="textlink" href="${servicePath(k)}">Explore ${k==='best'?'how to choose':k==='makers'?'cabinet construction':k==='showrooms'?'the showroom':t.replace('Kitchen Cabinets ','').replace('Kitchen Cabinet ','').toLowerCase()}</a></article>`).join('')}</section>`,'Understand kitchen cabinet pricing, design, customization, installation and showroom visits in Chicago.');
const serviceContent={pricing:['A quote you can understand.','Before comparing totals, compare what each proposal includes. A clear scope makes every other decision easier.',['Build a cabinet schedule','List each base, wall, tall and island cabinet with dimensions. Record filler panels, end panels and trim alongside the cabinet boxes.','Specify the construction','Identify the materials used in the doors, boxes and shelves, plus the finish and hardware. A collection name alone is not a complete specification.','Clarify the project scope','Separate cabinetry from assembly, delivery, installation, worktops, appliances and surrounding remodeling work. Confirm taxes and exclusions.']],installation:['A smooth handoff starts with a plan.','Cabinet installation depends on accurate measurements, a ready site and a clear sequence with the other trades.',['Confirm responsibilities','Identify who measures, prepares the site, receives the delivery and installs the cabinets. Confirm the installation service available for your address.','Prepare the room','Discuss wall condition, level floors, service locations and appliance requirements with the responsible installer. Avoid assuming the existing room is ready.','Agree on a project schedule','Ask for a project-specific timeline with dependencies and a process for damaged items or changes.']],custom:['Make room for your ideas.','A kitchen should respond to your space, storage needs and daily routines. Start with the parts that matter most.',['Set your priorities','Record what should stay, what needs to change and how you use the room. Include awkward corners, tall storage and appliance needs.','Explore the details','Bring finish references and a preferred door profile. Discuss which sizes and modifications the proposed cabinet line supports.','Review before ordering','A final drawing and written product specification should explain the exact layout, construction, finish and scope.']],makers:['Understand what your cabinets are made of.','Ask about the product, its components and who is responsible for each part of your order.',['Look beyond the front','Cabinet doors and boxes may use different materials. Ask for a component-level specification instead of assuming the entire cabinet matches its visible face.','Ask how customization works','Clarify available sizes, construction options, modifications and the approval process. Confirm actual manufacturing and sourcing information with the team.','Plan for long-term support','Review care, replacement parts, repair possibilities and the warranty attached to the exact product.']],remodel:['Cabinetry in the bigger picture.','A kitchen remodel involves more than cabinets. Make the boundaries of each supplier’s and contractor’s work clear.',['Start with the existing space','Document layout, appliances, plumbing, electrical services, access and any fixed constraints.','Coordinate the sequence','Discuss cabinetry with the contractor and other trades early enough to review openings, service locations and installation order.','Confirm the scope','Verify whether your proposal covers cabinetry only, installation or other remodeling work. Municipal requirements vary by location and project.']],design:['Design around your everyday.','Begin with how you cook, gather and store—not just how the room looks.',['Understand the routine','Which items should be close to preparation, cooking and cleanup? What should be easy to reach? Record the daily frustrations you want to solve.','Check the layout','Mark doors, windows, appliances and services. Confirm usable wall lengths and clearances before committing to cabinet dimensions.','Choose a coherent palette','View door, finish, worktop and flooring samples together. Then check construction and budget against the same specification.']],trends:['A considered outlook for 2027.','A design forecast, not a prediction of what every kitchen will look like. Choose what serves your home beyond a single season.',['Natural character','Visible grain and warm wood pair well with restrained surfaces. Use physical samples to decide what works in your light.','Grounded color','Deep olive and other rich finishes can create a calm focal point. Test colors alongside surrounding materials before committing.','Useful details','Thoughtful drawers, pantry storage and adaptable layouts put daily use ahead of decoration. These are editorial directions rather than measured market trends.']],best:['The best cabinet is the one that fits.','Use transparent criteria to compare proposals, rather than assuming one brand or construction label wins every time.',['Construction and fit','Compare component materials, hardware, dimensions, finish and the available modifications for your layout.','Total project scope','Compare the same cabinet schedule and separate delivery, assembly and installation costs.','Support and documentation','Ask about design review, written specifications, lead times, repair and warranty support. Amber Leaf’s fit should be assessed against your actual requirements.']]};
for(const [t,k] of services.filter(s=>s[1]!=='showrooms'&&s[1]!=='cost')){const [h,intro,sections]=serviceContent[k];page(servicePath(k),t,`${head('Chicago cabinet services',h,intro,['Services','/services/'])}<div class="wrap"><article class="content">${sections.map((x,i)=>i%2===0?`<h2>${x}</h2>`:`<p>${x}</p>`).join('')}<div class="inline-actions"><a class="btn" href="/start-order/">Start my cabinet order</a><a class="textlink" href="/showroom/">Visit the showroom</a></div><h2>Questions to bring to the team</h2><ul><li>What is included in this service for my project?</li><li>Who is responsible for dimensions and approvals?</li><li>What are the current pricing and timing assumptions?</li></ul><a href="/faq/">Explore frequently asked questions</a></article></div>`,`${t} in Chicago: explore project scope, planning priorities and the questions to ask before ordering.`);}
page('/showroom/','Visit Our Chicago Showroom',`${head('Every idea is welcome','Come in. Get inspired.','Homeowners, designers, contractors and developers—everyone is welcome at our Chicago showroom. Whether you are just browsing or ready to plan, bring your ideas.')}<section class="wrap split" style="padding-bottom:75px"><div class="split-image"><img src="/assets/finish-soft-white-room-v2.png" alt="White Shaker kitchen design inspiration"><p class="caption">Illustrative kitchen inspiration, not a showroom photograph.</p></div><div class="split-copy"><h2>See it.<br>Feel it.<br>Imagine it at home.</h2><p>Explore cabinet details and see how finishes work together. A conversation can start with a favorite color, a floor plan or simply an idea.</p><ul class="feature-list"><li>Homeowners exploring a first renovation</li><li>Designers considering materials and proportions</li><li>Contractors coordinating a kitchen project</li><li>Developers planning repeatable unit layouts</li></ul>${showroomContact()}</div></section><section class="section" style="background:var(--cream)"><div class="wrap grid2"><div><span class="eyebrow">Make the most of your visit</span><h2 style="font-size:44px">Bring what you have.</h2><p>Room photos, rough measurements, appliance dimensions and inspiration images are all useful. You do not need a finished design to begin exploring.</p><a class="btn" href="/start-order/">Create a visit-ready plan</a></div><div><h3>Find us in Chicago</h3><iframe title="Amber Leaf showroom location at 1201 W 36th Pl, Chicago" src="https://www.google.com/maps?q=1201%20W%2036th%20Pl%2C%20Chicago%2C%20IL%2060609&output=embed" width="100%" height="320" style="border:0" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe><p><a class="textlink" href="${directions}" target="_blank" rel="noopener">Get directions to the showroom</a></p><p>For a design consultation or questions before your visit, <a class="textlink" href="tel:+17732478282">call +1 773-247-8282</a> or <a class="textlink" href="mailto:info@amberleafhome.us">email our team</a>.</p><a class="textlink" href="/locations/">Explore the service area</a></div></div></section>`,'Everyone is welcome at the Amber Leaf Chicago showroom: homeowners, designers, contractors and developers.');
page('/locations/','Chicago-Area Locations Served',`${head('Near your next project','Chicago and the communities around it.','Explore our Chicago-area location guide. Confirm delivery, installation and visit arrangements for your exact address before planning a project.')}<div class="wrap"><div class="list-grid">${cities.map(c=>`<a href="/locations/${slug(c)}/">${c}</a>`).join('')}</div><section class="section grid2"><div><h2 style="font-size:42px">Start with your space.</h2><p>A useful cabinet plan connects your layout, priorities and product choices. Add your city or ZIP code so the team can discuss the next steps for your location.</p><a class="btn" href="/start-order/">Plan your cabinets</a></div><div><h3>Visit us in Chicago</h3><p>You are welcome at our Chicago showroom, wherever your project begins. Visit us Monday–Saturday, 9:00 AM–6:00 PM, at 1201 W 36th Pl, Chicago, IL 60609. Sunday: Closed.</p><a class="textlink" href="/showroom/">Plan your showroom visit</a></div></section></div>`,'Kitchen cabinet planning for Chicago, Oak Park, Evanston, Naperville and surrounding communities.');
function locationProjectContent(city){return `<section class="section wrap"><span class="eyebrow">Your project in ${city}</span><h2>Is Amber Leaf right<br>for your project?</h2><p class="location-intro">Start with the room, the people who use it and the support you need. Our Chicago showroom is a place to explore your options; confirm the cabinet specification, service coverage and schedule for your ${city} address before ordering.</p><div class="grid3"><article class="editorial-card"><h3>A kitchen for your home</h3><p>Bring renovation or new-home plans, whether you want a compact layout, more everyday storage or an island for gathering. Compare door styles and finishes against your flooring and worktop ideas.</p></article><article class="editorial-card"><h3>A contractor or development brief</h3><p>Amber Leaf collaborates with general contractors and developers on projects from 5 to 5,000 units. Bring unit layouts, a cabinet schedule, quantities and delivery phases to begin a project conversation.</p></article><article class="editorial-card"><h3>The scope you need</h3><p>Tell us whether you need cabinet supply only or want to discuss installation. Exact dimensions, customization, delivery access and installation responsibilities need a project-specific review.</p></article></div><div class="inline-actions"><a class="btn" href="/start-order/">Prepare your project brief</a><a class="textlink" href="tel:+17732478282">Confirm service for your address</a></div></section><section class="section" style="background:var(--cream)"><div class="wrap"><span class="eyebrow">What to expect</span><h2>From first ideas<br>to a clear cabinet plan.</h2><div class="grid2"><article class="editorial-card"><span class="eyebrow">01 · Prepare</span><h3>Bring what you have</h3><p>Room photographs, approximate wall lengths, appliance dimensions and your budget priorities help frame the conversation. You can begin with inspiration even if your measurements are incomplete.</p></article><article class="editorial-card"><span class="eyebrow">02 · Explore</span><h3>Visit the Chicago showroom</h3><p>Everyone is welcome at 1201 W 36th Pl. Explore finishes and cabinet details in person, and discuss how your kitchen should work. Call ahead if you want to discuss a specific project or product.</p></article><article class="editorial-card"><span class="eyebrow">03 · Review</span><h3>Confirm the proposed specification</h3><p>Ask for door and box materials, dimensions, storage accessories, hardware and finish details. Review the layout against site measurements before approving an order.</p></article><article class="editorial-card"><span class="eyebrow">04 · Coordinate</span><h3>Agree on the complete scope</h3><p>Confirm pricing inclusions, lead time, delivery to ${city}, site readiness and who handles installation. A downloaded website plan starts the discussion; it does not submit a request or place an order.</p></article></div></div></section><section class="section wrap"><span class="eyebrow">Choose with confidence</span><h2>Compare more<br>than the cabinet price.</h2><p class="location-intro">Choose Amber Leaf if you value seeing materials in person, discussing design priorities and bringing a homeowner or development brief to one cabinetry conversation. Assess competing proposals against the same layout and specifications.</p><div class="grid3"><article class="editorial-card"><h3>See the details before deciding</h3><p>Use the Chicago showroom to compare physical finishes, door profiles and storage details. Ask any supplier how you can inspect the exact product being quoted.</p></article><article class="editorial-card"><h3>Consider your project’s scale</h3><p>Amber Leaf’s work with contractors and developers spans 5 to 5,000 units. For your project, ask how specifications, quantities and site coordination will be documented.</p></article><article class="editorial-card"><h3>Ask for evidence behind the claims</h3><p>Our commitment to sustainability, community partnerships and good design should lead to specific questions. Request sourcing and emissions documentation for the proposed product, alongside maintenance and warranty terms.</p></article></div><p class="caption">Compare a cabinet-by-cabinet schedule, product specifications, exclusions and service responsibilities. There is no universal best choice for every kitchen.</p><a class="textlink" href="/projects/#comparisons">Explore cabinet comparison guides</a></section>`;}
function beforeAfter(id){return `<div class="before-after" style="--split:50%"><img class="comparison-after" src="/assets/naperville-after-oak.png" alt="After mock-up: natural oak Shaker cabinetry, natural oak island and light worktops" loading="lazy"><img class="comparison-before" src="/assets/naperville-before-worn.png" alt="Before mock-up: worn dated oak cabinets and scratched laminate counters" loading="lazy"><span class="comparison-label before-label">Before</span><span class="comparison-label after-label">After</span><span class="comparison-divider" aria-hidden="true"><span>↔</span></span><label class="visually-hidden" for="${id}">Slide to compare the fictional kitchen before and after</label><input id="${id}" type="range" min="0" max="100" value="50" data-comparison-slider aria-valuetext="50% before, 50% after"></div>`;}
function napervilleCaseStudy(){return `<section class="section" style="background:var(--cream)"><div class="wrap"><span class="eyebrow">Naperville · fictional design concept</span><div class="split"><div class="case-comparison">${beforeAfter('naperville-comparison')}<p class="caption">Drag to compare the worn, dated kitchen with the proposed renovation. Generated mock-up images, not completed customer photographs.</p></div><div><span class="mock-label" style="margin:0 0 20px">Mock-up case study</span><h2 style="font-size:42px">More room for<br>everyday family life.</h2><p>A fictional Naperville household wants to replace a kitchen with limited preparation space and awkward storage. Their brief brings together warm oak doors, a contrasting island and a place for the family to gather.</p><dl class="case-facts"><div><dt>Project</dt><dd>Illustrative homeowner renovation</dd></div><div><dt>Room</dt><dd>14 × 18 ft · assumed dimensions</dd></div><div><dt>Cabinet concept</dt><dd>18-cabinet Shaker layout with an island</dd></div><div><dt>Cabinet pricing</dt><dd>Quote required after specification review</dd></div></dl><h3>The challenge</h3><p>Make daily cooking and storage easier while keeping the kitchen welcoming for shared meals.</p><h3>The proposed approach</h3><p>Group preparation storage near the worktop, reserve a zone for pantry items and review island seating against appliance doors and circulation space. Compare oak and painted finish samples in the showroom before choosing a palette.</p><h3>What success would look like</h3><p>A layout with clearer storage zones, useful preparation space and comfortable circulation. A measured plan and customer feedback would be needed to verify these outcomes.</p><p class="caption">All household details, specifications and dimensions are examples. A quote must clarify installation, countertops, appliances, decorative hardware, delivery and tax. No customer testimonial or measured result is implied.</p><a class="btn" href="/start-order/?collection=natural-oak">Plan a similar kitchen</a></div></div></div></section>`;}
function neighborhoodProjects(city){return `<section class="section wrap" id="neighborhood-projects"><div class="section-head"><div><span class="eyebrow">Local projects · Photos · Design details</span><h2>Ideas for a kitchen<br>in your neighborhood.</h2></div><p>Explore the details that could fit your ${city} project. These are sample design studies; verified nearby customer projects have not yet been added.</p></div><div class="grid3">${collections.map((c,i)=>`<article class="portfolio-card"><a href="/chicago-kitchen-cabinets/collections/${c.id}/"><img src="/assets/${c.image}" alt="${c.name} sample kitchen concept for project planning" loading="lazy" style="width:100%;aspect-ratio:3/2;object-fit:cover"></a><div class="portfolio-copy"><span class="tag">Sample project · not a completed local installation</span><h3>${['Family kitchen renovation','Modern kitchen concept','Classic kitchen refresh'][i]}</h3><p>${c.style==='Modern'?'Modern slab':c.style} · ${c.finish}</p><dl><dt>Materials</dt><dd>${c.doorMaterial}; ${c.boxMaterial} cabinet boxes</dd><dt>Design priority</dt><dd>${['Balance preparation space, pantry storage and island seating.','Keep clean lines while planning useful tall storage.','Bring light finishes and organized drawers into everyday use.'][i]}</dd><dt>Illustrative cabinet budget</dt><dd>${c.priceEstimate} · supply only</dd></dl><a class="textlink" href="/chicago-kitchen-cabinets/collections/${c.id}/">See photos & design details</a></div></article>`).join('')}</div><p class="caption">Sample materials and budgets require confirmation. Installation, worktops, appliances, decorative hardware, delivery and tax are excluded.</p><div class="inline-actions"><a class="btn" href="/projects/?location=${encodeURIComponent(city)}#portfolio">Browse local portfolio</a><a class="textlink" href="/showroom/">Ask about projects similar to yours</a></div></section>`;}
const localPlanningPrompts=["Bring your existing cabinet count and note which storage items are hard to reach.","Share the cabinet elevations and appliance specifications for any coordinated renovation.","Record doorway widths and the route planned for cabinet delivery.","Photograph plumbing and electrical locations before planning new cabinet runs.","Bring door-profile ideas and describe the details you want your new cabinetry to retain.","Identify worktop preparation areas and corner cabinets that are difficult to use.","Mark walls and openings on a rough plan before comparing cabinet widths.","Share island seating needs alongside the appliance-door clearances.","Explore the fictional family-kitchen example, then bring your own layout and storage priorities.","List pantry and grocery storage needs before choosing tall cabinet components.","Record everyday dishes, cookware and recycling needs to build a useful accessory brief.","Provide building access rules and delivery arrangements if your project has shared entrances.","Share the dimensions of narrow gaps and any nonstandard cabinet requirements.","For a larger project, send unit counts and repeated cabinet schedules for review.","Describe how multiple cooks use the space and which drawers they need close by.","Bring room photos, a preferred finish palette and an installation-scope question list."];
for(const [i,city] of cities.entries()){page('/locations/'+slug(city)+'/', 'Kitchen Cabinets '+city, head('Chicago-area cabinet planning','Kitchen cabinets in '+city+'.','Plan your project with our Chicago showroom. This guide is not a local branch listing.',['Locations','/locations/'])+(city==='Naperville'?napervilleCaseStudy():'')+travelSection(city)+'<section class="wrap section"><span class="eyebrow">Your '+city+' planning brief</span><h2>Start with your home and your priorities.</h2><p>'+localPlanningPrompts[i]+'</p><div class="grid2"><article><h3>Can we help with your project?</h3><p>Explore complete cabinetry, door finishes and functional interior storage. Confirm delivery, design support and installation availability for your exact '+city+' address before committing.</p><a class="btn" href="/start-order/?location='+encodeURIComponent(city)+'">Build your '+city+' cabinet plan</a></article><article><h3>What to expect</h3><p>Start with rough measurements or request design help. The team must review site measurements, accessory clearances, final specifications and an itemized quote before manufacturing.</p><a class="textlink" href="/how-it-works/">See the process and responsibilities</a></article></div><h3>Local project evidence</h3><p>Verified '+city+' customer photography and project details have not yet been supplied. Ask the team for relevant completed work before selecting a supplier.</p><a class="textlink" href="/projects/">Explore clearly labeled design concepts</a><h3>Why consider Amber Leaf?</h3><p>Plan complete cabinet components, visible finishes and interior accessories in one place, with a Chicago showroom to discuss your choices. Compare written specifications, responsibilities and total scope with other suppliers.</p></section><section class="section" style="background:var(--cream)"><div class="wrap grid2"><div><h2>Visit from '+city+'.</h2>'+showroomContact()+'</div><div><h3>Questions to confirm</h3><details><summary>Is there a showroom in '+city+'?</summary><p>This page represents service-area planning. Our showroom address is in Chicago.</p></details><details><summary>Are installation and delivery available at my address?</summary><p>Call or email with your address, project scope and access requirements. Availability and timing require confirmation.</p></details><details><summary>Can I start without exact measurements?</summary><p>Yes. Choose design help in the planner, or bring photos and rough wall lengths to discuss your starting point.</p></details><a class="textlink" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(city+', Illinois')+'">View '+city+' on Google Maps</a></div></div></section>','Cabinet planning and Chicago showroom information for '+city+'.','noindex,follow');}

function portfolio(){return `<section class="wrap" id="portfolio" style="padding-bottom:70px"><span class="eyebrow">Project portfolio</span><p>Explore concepts by room, style and planning location. Generated design studies are not completed customer projects. Product prices have not been verified.</p><div class="filters portfolio-filters"><label>Room<select data-project-filter="room"><option value="">All rooms</option><option>Kitchen</option><option>Bathroom</option></select></label><label>Style<select data-project-filter="style"><option value="">All styles</option><option>Shaker</option><option>Modern</option></select></label><label>Price status<select data-project-filter="budget"><option value="">All price statuses</option><option value="quote">Quote required</option></select></label><label>Location<select data-project-filter="location"><option value="">All locations</option><option value="unassigned">Design study · no location</option>${cities.map(city=>`<option>${city}</option>`).join('')}</select></label><button class="btn outline" id="clear-project-filters">Clear filters</button></div><p role="status" id="project-count"></p><div class="grid3" id="project-grid">${collections.map((c,i)=>`<article class="portfolio-card" data-project-room="Kitchen" data-project-style="${c.style}" data-project-budget="quote" data-project-location="${i===0?'Naperville':'unassigned'}"><div class="portfolio-image"><img src="/assets/${c.image}" alt="${c.name} fictional kitchen design" loading="lazy" data-project-photo>${i===0?'<div class="project-view-controls" role="group" aria-label="View fictional renovation"><button type="button" data-project-view="before" aria-pressed="false">Before</button><button type="button" data-project-view="after" aria-pressed="true">After</button></div>':''}</div><div class="portfolio-copy"><span class="tag">${i===0?'Naperville · fictional family renovation':'Unassigned location · design study'}</span><h3>${i===0?'Room for everyday family life':c.name}</h3><p>${c.style==='Modern'?'Modern slab':c.style} · ${c.finish}</p><dl><dt>Project type</dt><dd>Kitchen · ${i===0?'sample renovation':'design concept'}</dd><dt>Materials</dt><dd>${c.doorMaterial}; ${c.boxMaterial} boxes</dd><dt>Price status</dt><dd>${c.priceEstimate} · supply only</dd></dl><details><summary>Design challenge & approach</summary><p>${['A family needs clearer preparation and pantry zones. The proposed oak perimeter and natural oak island bring storage and gathering together; measured clearances must be reviewed.','A kitchen needs visual simplicity with useful storage. Flat olive fronts and coordinated tall cabinetry create a calm palette; appliance access and storage capacity need a measured review.','A homeowner wants a familiar, light kitchen with organized storage. White Shaker fronts and a pale worktop form the concept; drawer functions and circulation need confirmation.'][i]}</p><p>Proposed design only. No measured customer outcomes or verified local team attribution are available.</p></details><a class="textlink" href="${i===0?'/locations/naperville/':'/chicago-kitchen-cabinets/collections/'+c.id+'/'}">${i===0?'View the sample family story':'Explore this design'}</a></div></article>`).join('')}</div><div id="project-empty" class="notice" hidden><h3>No matching project examples yet</h3><p>Try another filter or clear your choices. Bathroom and additional local customer portfolios will appear when verified project photography and details are available.</p><a class="textlink" href="/kitchen-survey/">Tell us about your kitchen</a></div></section>`;}
page('/projects/','Projects & Cabinet Comparisons',`${head('Inspiration meets practical thinking','A room for every way of living.','Explore design studies, then compare the choices behind them. Our inspiration images are illustrative; verified Amber Leaf project stories will be added with permission-cleared photographs.')}${portfolio()}<section class="section dark-section"><div class="wrap"><span class="eyebrow">Contractors & developers</span><h2>Good design.<br>At every scale.</h2><p style="max-width:600px">Amber Leaf collaborates with respected general contractors and developers on projects ranging from 5 to 5,000 units. Start with unit layouts, specifications and the needs of your project.</p><a class="btn" href="/professionals/">Explore project planning</a></div></section><section class="section wrap" id="comparisons"><div class="section-head"><div><span class="eyebrow">Compare your options</span><h2>Know what<br>you’re choosing.</h2></div><p>Construction, style, materials and service all matter. These guides help you ask better questions.</p></div><div class="grid3">${comparisons.map(([t,s])=>`<article class="editorial-card"><h3>${t}</h3><p>Understand the tradeoffs and compare the right details.</p><a class="textlink" href="/projects/comparisons/${s}/">Read the guide</a></article>`).join('')}</div></section>`,'Kitchen design inspiration and practical comparisons: IKEA, retailer cabinets, custom cabinetry, Shaker, modern, oak and maple.');
for(const [title,s] of comparisons){const isStyle=s==='shaker-vs-modern-cabinets',isWood=s==='white-oak-vs-maple-cabinets',isTypes=s==='stock-semi-custom-custom';const rows=isStyle?[['Door profile','A frame around a recessed center panel','A flat, continuous front'],['Visual character','Framed detail that can feel traditional or contemporary','A restrained profile that emphasizes finish and proportion'],['What to compare','Frame width, finish, proportions and hardware','Edge detail, finish, hardware and alignment']]:isWood?[['Appearance','Consider the oak grain and the exact finish sample','Consider the maple grain and the exact finish sample'],['Construction','Check how the species is used in the door or other component','Check how the species is used in the door or other component'],['Cost and performance','Use the actual product specification and quote','Use the actual product specification and quote']]:[['Fit and sizing','Check the exact line’s size range and modification options','Confirm the proposed dimensions and customization scope'],['Construction','Review component materials and hardware for the selected product','Review the written door, box, shelf and hardware specification'],['Project cost','Separate product, assembly, accessories, delivery and installation','Compare the same itemized layout and inclusion list'],['Support','Confirm who handles design, measurements, installation and warranty','Confirm the team’s responsibilities and written support terms']];page(`/projects/comparisons/${s}/`,title,`${head('Make an informed choice',title,isStyle?'A door profile is a starting point, not a whole design. Compare the shapes, proportions and finish in the context of your room.':isWood?'Choose from physical samples and a complete product specification. A wood species alone does not describe the whole cabinet.':'Compare the actual products and project scope. A retailer, brand or construction label does not tell you everything about a cabinet.', ['Projects','/projects/'])}<div class="wrap"><article class="content"><h2>Which option fits your needs?</h2><p>${isStyle?'Shaker can bring framed detail and familiarity; slab fronts can create a simpler visual rhythm. Both can suit modern homes. The best fit depends on your proportions, palette and preferred details.':isWood?'White oak and maple offer different visual starting points. View samples under your lighting, then compare door construction, finish, availability and the complete quote. Neither species is automatically the best choice for every project.':isTypes?'Stock typically offers established configurations, semi-custom adds selected options, and custom work responds to a more specific brief. Terminology and modification ranges vary by supplier, so confirm the actual choices.':'Established product systems may suit a layout that works within their available options. A custom specification may be useful when particular dimensions, details or coordination needs are central to the project. Ask what the exact line or proposal includes.'}</p><div class="table-wrap"><table><thead><tr><th>Compare</th><th>${isStyle?'Shaker':isWood?'White oak':'Specified product or line'}</th><th>${isStyle?'Modern slab':isWood?'Maple':'Custom proposal'}</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map((x,i)=>i===0?`<th scope="row">${x}</th>`:`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h2>Where Amber Leaf may fit</h2><p>Consider Amber Leaf when you want a cabinet conversation connected to your room or development. Bring the layout, preferred details and coordination requirements so the team can explain available options and service scope.</p><h2>Before deciding</h2><ul><li>Compare the same cabinet schedule and exact dimensions.</li><li>Use dated specifications and current written quotes.</li><li>Review physical finish samples and warranty terms.</li><li>Identify who approves measurements and handles changes.</li></ul><p class="caption">This is a comparison framework, not a verified review of current retailer lines or a price ranking. Named retailers offer multiple product ranges. Updated October 2026.</p><div class="inline-actions"><a class="btn" href="/start-order/">Plan your cabinet requirements</a><a class="textlink" href="/resources/cabinet-materials-guide/">Read the materials guide</a></div></article></div>`,`${title}: a practical framework for comparing cabinet specification, fit, cost scope and project support.`);}
page('/faq/','Frequently Asked Questions',`${head('A little clarity goes a long way','Your cabinet questions, answered.','Find guidance on budgeting, materials, design and the path from a first idea to an approved order.')}<div class="wrap" style="padding-bottom:75px"><div class="faq-categories" role="group" aria-label="Filter questions by category"><button class="faq-category" data-faq-category="all" aria-pressed="true"><span>All questions</span><small>20 questions</small></button>${faqGroups.map(([g,qs],i)=>`<button class="faq-category" data-faq-category="${i}" aria-pressed="false"><span>${g}</span><small>${qs.length} questions</small></button>`).join('')}</div><label class="visually-hidden" for="faq-search">Search FAQs</label><input class="faq-search" id="faq-search" type="search" placeholder="Search questions, e.g. materials or installation"><p id="faq-count" class="results-label" role="status">20 questions</p>${faqGroups.map(([g,qs],i)=>`<section class="faq-section" data-faq-group="${i}"><h2>${g}</h2>${qs.map(([q,a],j)=>`<details data-faq id="faq-${i}-${j}"><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`).join('')}<div id="faq-empty" class="empty" hidden>No matching questions. Try a broader term, such as “cost” or “design.”</div><a class="textlink" href="/showroom/">Bring your questions to the showroom</a></div>`,'Twenty kitchen cabinet FAQs covering costs in Chicago, materials, durability, design, delivery and installation.');
page('/resources/','Cabinet Guides & Resources',`${head('Useful knowledge. Better decisions.','Make space for a little know-how.','Practical guides to cabinet scope, materials and kitchen planning. Research sources are included where they inform environmental topics.')}<section class="wrap grid3" style="padding-bottom:80px">${guides.map(([t,s,d,c])=>`<article class="editorial-card"><span class="eyebrow">${c}</span><h3>${t}</h3><p>${d}</p><a class="textlink" href="/resources/${s}/">Read the guide</a></article>`).join('')}</section>`,'Cabinet cost, materials, kitchen design, Chicago remodeling and homeowner planning guides.');
const research=`<h2>Research notes</h2><p>Peer-reviewed furniture research offers useful background on life-cycle assessment and design for environment. It does not establish the impact, certification or service life of an Amber Leaf cabinet.</p><ul><li><a href="https://pubmed.ncbi.nlm.nih.gov/22542234/" target="_blank" rel="noopener">Eco-innovation of a wooden childhood furniture set</a>, <em>Science of the Total Environment</em> (2012): an example of using life-cycle and design-for-environment methods for furniture.</li><li><a href="https://pubmed.ncbi.nlm.nih.gov/35019094/" target="_blank" rel="noopener">Environmental sustainability assessment of wooden furniture produced in Pakistan</a>, <em>Environmental Science and Pollution Research</em> (2022): background on production inputs and assessment scope in a different manufacturing context.</li></ul><p>For a product decision, request documentation for the exact material, finish and supplier. Do not transfer a study’s findings to a different product without checking its scope and methods.</p>`;
const guideBodies={
'cabinet-cost-guide':`<h2>A budget starts with a scope</h2><p>Two quotes can describe very different kitchens. A meaningful comparison begins with the same cabinet schedule, construction and finish—not simply the same number of doors.</p><h2>Build an itemized schedule</h2><p>List base cabinets, wall cabinets, tall storage, drawer units and island cabinets. Add exact dimensions, finished end panels, fillers, trim, hardware and accessories. Count cabinet boxes separately from doors and drawers.</p><div class="table-wrap"><table><thead><tr><th>Budget category</th><th>What to confirm</th></tr></thead><tbody><tr><th>Cabinetry</th><td>Boxes, doors, shelves, finish and included hardware</td></tr><tr><th>Accessories</th><td>Drawer organizers, pantry systems and specialty storage</td></tr><tr><th>Delivery & assembly</th><td>Delivery scope, assembly state and site access</td></tr><tr><th>Installation</th><td>Labor, preparation, trim and exclusions</td></tr><tr><th>Other work</th><td>Worktops, appliances, electrical, plumbing and surrounding remodeling</td></tr></tbody></table></div><h2>Use sample packages carefully</h2><p>A five-cabinet example may help you visualize a compact kitchen, but cabinet width, construction and accessories still change the total. Room area alone cannot tell you how many cabinets fit.</p><h2>Ask for a dated quote</h2><p>Confirm taxes, exclusions, lead-time assumptions and the process for changes. Current Amber Leaf prices are project-specific; this guide does not provide verified Chicago market price ranges.</p>`,
'chicago-remodeling-guide':`<h2>Document what exists</h2><p>Photograph the room and record wall lengths, ceiling height, doors, windows, appliance dimensions and service locations. Note anything that must remain in place.</p><h2>Agree on responsibilities</h2><p>Identify who designs, measures, orders, prepares the site and installs. Cabinet drawings should be coordinated with the other trades and appliance requirements.</p><h2>Plan the sequence</h2><ol><li>Survey the room and clarify the scope.</li><li>Review design and product specifications.</li><li>Confirm required approvals with the responsible professional.</li><li>Coordinate ordering, site preparation and delivery.</li><li>Install, inspect and document the completed work.</li></ol><h2>Check local requirements</h2><p>Requirements depend on the actual work and municipality. For Chicago, begin with the <a href="https://www.chicago.gov/city/en/depts/bldgs.html" target="_blank" rel="noopener">City of Chicago Department of Buildings</a>. For a surrounding community, consult its own building department. This guide does not determine whether your project needs a permit.</p>`,
'cabinet-materials-guide':`<h2>Look beyond the door</h2><p>A cabinet is a system of doors, boxes, shelves, drawers, hardware and finishes. A visible oak door does not mean the entire cabinet is solid oak.</p><h2>Compare materials by component</h2><div class="table-wrap"><table><thead><tr><th>Component</th><th>Questions to ask</th></tr></thead><tbody><tr><th>Door</th><td>What material, construction and finish are specified?</td></tr><tr><th>Cabinet box</th><td>What are the panel material, thickness and edge details?</td></tr><tr><th>Shelves & drawers</th><td>What support, dimensions and load guidance apply?</td></tr><tr><th>Hardware</th><td>What hinges and runners are included, and can parts be replaced?</td></tr><tr><th>Finish</th><td>What cleaning, moisture and maintenance instructions apply?</td></tr></tbody></table></div><h2>Wood and wood-based panels</h2><p>Solid wood, plywood and MDF describe different material forms. They can be used in different components of the same cabinet. Ask for actual specifications and documented performance rather than assuming one label makes a complete cabinet better.</p><h2>Environmental claims need a scope</h2><p>Request sourcing, emissions and certification records linked to the exact product. Consider repair and replacement options as part of your decision.</p>${research}`,
'kitchen-design-guide':`<h2>Begin with daily routines</h2><p>Think about the things you reach for while preparing, cooking, serving and cleaning. Record the storage you need and the movement you want the layout to support.</p><h2>Measure the usable space</h2><p>Wall lengths alone are not enough. Mark openings, appliance requirements, plumbing and electrical services. A final layout needs dimensions and clearance checks by the responsible designer or installer.</p><h2>Plan storage intentionally</h2><ul><li>Record tall items, cookware and pantry needs.</li><li>Discuss drawers, shelves and specialty accessories.</li><li>Think about access for everyone using the room.</li><li>Check how doors and drawers open near corners and appliances.</li></ul><h2>Build the palette in person</h2><p>Place cabinet samples alongside flooring and worktop samples. View them in the room’s light before approving a finish. Screen images and generated design studies are useful inspiration, not exact finish references.</p><h2>Review the whole plan</h2><p>Confirm the cabinet schedule, dimensions, materials, accessories, responsibilities and cost scope together. A beautiful image cannot replace an approved specification.</p>`,
'chicago-homeowner-guide':`<h2>Compare proposals, not slogans</h2><p>Ask suppliers to explain the exact cabinet specification and scope. Compare the same layout and understand who is responsible for every project stage.</p><h2>Your first conversation</h2><ul><li>Bring room photographs and rough measurements.</li><li>List existing appliances and anything that must stay.</li><li>Save door profiles, finishes and storage ideas you like.</li><li>Record your preferred budget and schedule as discussion points.</li></ul><h2>Before you approve an order</h2><p>Review written drawings, final dimensions, component materials, finish samples, hardware, price, exclusions, lead time and service terms. Confirm how changes and damaged items will be handled.</p><h2>Keep a project record</h2><p>Save the approved cabinet schedule, product documentation, invoices and warranty information. Follow the specified care guidance for the actual finish.</p><h2>Start local</h2><p>Everyone is welcome at our Chicago showroom: 1201 W 36th Pl, Chicago, IL 60609. Hours are Monday–Saturday, 9:00 AM–6:00 PM; Sunday: Closed. Call <a href="tel:+17732478282">+1 773-247-8282</a> for help planning your visit.</p>`};
for(const [t,s,d,c] of guides){page(`/resources/${s}/`,t,`${head(c,t,d,['Resources','/resources/'])}<div class="wrap"><article class="content"><p class="tag">Amber Leaf planning guide · Updated October 2026</p>${guideBodies[s]}<div class="inline-actions"><a class="btn" href="/start-order/">Put these ideas in your plan</a><a class="textlink" href="/faq/">More cabinet questions</a></div></article></div>`,`${t}: ${d}`);}
page('/professionals/','Cabinetry for Contractors & Developers',`${head('A partner in your project','Thoughtful cabinetry.<br>At development scale.','Amber Leaf collaborates with general contractors and developers on projects ranging from 5 to 5,000 units, with a commitment to sustainability, community partnerships and good design.')}<div class="wrap split" style="padding-bottom:70px"><div class="split-image"><img src="/assets/color-charcoal-gray.png" alt="Modern olive cabinet design study"><p class="caption">Illustrative design study.</p></div><div><span class="eyebrow">Begin with the brief</span><h2 style="font-size:42px">Bring the details<br>that matter.</h2><ul class="feature-list"><li>Unit count and repeated kitchen layouts</li><li>Cabinet schedule and material priorities</li><li>Delivery phasing and site logistics</li><li>Design review and installation responsibilities</li><li>Bid deadline and target project sequence</li></ul><a class="btn" href="/start-order/?type=Professional">Build a project brief</a></div></div><section class="section" style="background:var(--cream)"><div class="wrap grid3"><div><h3>Consistent specifications</h3><p>Document what repeats across units and where layouts or finishes vary.</p></div><div><h3>Clear handoffs</h3><p>Confirm design approvals, site readiness, delivery and installation scope.</p></div><div><h3>Responsible choices</h3><p>Discuss sourcing documentation, serviceability and community priorities.</p></div></div></section>`,'Amber Leaf cabinetry planning for contractors and developers, from 5 to 5,000 units.');
page('/sustainability/','Sustainability & Community',`${head('Considered choices, lasting relationships','Good design has a bigger purpose.','Our commitment to sustainability, community partnerships and good design shapes the conversations we have about cabinetry.')}<div class="wrap"><article class="content"><h2>Ask for evidence</h2><p>Meaningful material choices begin with product-specific information. Ask about sourcing, emissions documentation, certification scope and the care required by the selected finish.</p><h2>Think beyond the first day</h2><p>Discuss durability, repair, hardware replacement and how components can be maintained. A kitchen should continue to serve the people using it.</p><h2>Build with the community in mind</h2><p>Our company commitment includes community partnerships. Specific partner stories and supporting documentation will be added when approved for publication.</p>${research}<a class="textlink" href="/resources/cabinet-materials-guide/">Explore cabinet materials</a></article></div>`,'Amber Leaf’s commitment to sustainability, community partnerships and evidence-informed cabinet choices.');
page('/about/','About Amber Leaf',`${head('Chicago cabinetry','Designed around people.','We work with homeowners, designers, contractors and developers who believe a kitchen should be both beautiful and useful.')}<div class="wrap"><article class="content"><h2>From a home to a development</h2><p>Amber Leaf collaborates with many of the country’s respected general contractors and developers on projects ranging from 5 to 5,000 units. Sustainability, community partnerships and good design are central to our company’s commitment.</p><h2>Everyone is welcome</h2><p>You do not need a complete design to visit our Chicago showroom. Bring your ideas, questions and materials you want to explore.</p><div class="inline-actions"><a class="btn" href="/showroom/">Plan a showroom visit</a><a class="textlink" href="/professionals/">Contractors & developers</a></div></article></div>`,'Learn about Amber Leaf cabinetry and our welcoming Chicago showroom.');
function colorShowcase(){return `<section class="section wrap"><div class="section-head"><div><span class="eyebrow">Our cabinet color palette</span><h2>Popular shades.<br>A Midwest special edition.</h2></div><p>Explore Soft White, Natural Oak and Charcoal Gray, plus our Midwest-inspired Warm Ivory special edition. Find a palette you love, then match it to the cabinet sizes and storage your home needs.</p></div><div class="color-demo-grid">${[{"name":"Soft White","id":"soft-white","material":"MDF with durable painted or laminate surface","finish":"Matte / satin"},{"name":"Warm Ivory","id":"warm-ivory","material":"MDF with durable painted or laminate surface","finish":"Matte / satin"},{"name":"Natural Oak","id":"natural-oak","material":"Oak-look textured laminate on engineered wood","finish":"Natural wood grain"},{"name":"Charcoal Gray","id":"charcoal-gray","material":"MDF with dark laminate or painted finish","finish":"Matte"}].map(c=>`<article class="color-demo-card"><a href="/start-order/?color=${encodeURIComponent(c.name)}"><img src="/assets/color-${c.id}.png" alt="${c.name} kitchen finish demo" loading="lazy"></a>${c.id==='warm-ivory'?'<span class="regional-badge">Midwest special edition</span>':''}<h3>${c.name}</h3><p>${c.material}</p><span class="color-finish">${c.finish}</span><a class="textlink" href="/start-order/?color=${encodeURIComponent(c.name)}">Plan with ${c.name}</a></article>`).join('')}</div><div class="palette-consult"><div><h3>A specific size or color in mind?</h3><p>Consult with our team about your measurements, custom color preferences and storage needs. We’ll help review suitable options and confirm what’s available for your project.</p></div><div class="inline-actions"><a class="btn" href="/kitchen-survey/">Tell us what you need</a><a class="textlink" href="/showroom/">Consult with our team</a></div></div><p class="caption">Illustrative color previews. Warm Ivory is a Midwest-inspired special edition concept, not a verified regional popularity ranking. Confirm samples, specifications and availability with Amber Leaf.</p></section>`;}
function surveyInvite(){return `<section class="section survey-invite"><div class="wrap split"><div><span class="eyebrow">Factory-direct pricing · Cabinets + storage</span><h2 style="font-size:44px">Plan the whole kitchen.<br>Inside and out.</h2><p>Get factory-direct pricing on cabinets, explore a wide range of cabinet sizes, and plan functional interior storage in one online request. From deep drawers to spice pull-outs and concealed bins, start with how you live—then choose the cabinets and finishes you love. Explore the dots to see the details.</p><div class="inline-actions"><a class="btn" href="/kitchen-survey/">Tell us about your kitchen</a><a class="textlink" href="/start-order/">Request your online order</a></div><p class="caption">Begin without detailed measurements. Review the final layout, specification and quote with our team before ordering.</p><a class="textlink" href="/services/">Explore our services</a><div class="factory-benefits"><span>Factory-direct cabinet pricing</span><span>A wide variety of cabinet sizes</span><span>Cabinets + interior accessories together</span></div></div><div>${hotspot}<p class="caption">Tap the dots to explore oak doors, drawers and island storage. Illustrative design study.</p><details><summary>Details in this image</summary><p>Natural oak doors, everyday drawer storage and an natural oak island. Confirm final materials, hardware, availability and pricing with your project specification.</p></details></div></div></section><section class="section" style="background:var(--cream)"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Start with what you need to store</span><h2>A place for everything<br>you use every day.</h2></div><p>Tell us what is hard to reach or organize. Explore storage solutions before choosing the final cabinet look.</p></div><div class="home-storage-grid">${[['Pots & pans','Deep drawers keep cookware easy to reach.','Pots & pans storage'],['Spices & ingredients','Pull-outs and drawer inserts help you find small essentials.','Spice organization'],['Trash & recycling','Concealed bins keep everyday waste organized.','Trash & recycling'],['Awkward corners','Corner pull-outs bring hidden storage within reach.','Corner storage']].map(([title,copy,value],i)=>`<a class="storage-intent" href="/start-order/?storage=${encodeURIComponent(value)}"><span class="storage-number">0${i+1}</span><h3>${title}</h3><p>${copy}</p><span class="textlink">Plan this storage need →</span></a>`).join('')}</div><p class="caption">Available accessories and fit depend on your cabinet dimensions and product selection.</p></div></section><section class="section wrap factory-comparison"><span class="eyebrow">Shopping for your kitchen?</span><h2>A complete cabinet plan.<br>One place to begin.</h2><p>Considering IKEA, Wayfair, Home Depot or Menards? Compare the cabinet dimensions, construction and complete project scope. At Amber Leaf, explore factory-direct cabinet pricing, a wide variety of sizes and functional storage solutions together—with design and installation support to discuss as part of your request.</p><div class="inline-actions"><a class="btn" href="/start-order/">Explore cabinets & storage</a><a class="textlink" href="/projects/#comparisons">Compare cabinet options</a></div><p class="caption">Confirm available sizes, accessories, specifications and final pricing for your project.</p></section><section class="section wrap"><div class="grid2"><div><span class="eyebrow">Understand your budget early</span><h2>See a starting estimate.<br>Refine it together.</h2><p>Choose a kitchen size, collection, cabinet count and storage preferences to see an illustrative cabinetry estimate while you plan. No detailed measurements are needed to explore a starting budget.</p><a class="btn" href="/start-order/">Explore my estimated budget</a></div><div class="editorial-card"><h3>What shapes the final quote?</h3><ul class="feature-list"><li>Exact room dimensions and cabinet schedule</li><li>Door style, materials, color and finish</li><li>Interior accessories, storage systems and hardware</li><li>Design support, delivery and installation scope</li></ul><p class="caption">Online estimates use mock prices and allowances. Installation, design fees, delivery, tax, countertops and appliances are excluded unless expressly quoted.</p></div></div></section><section class="section" style="background:var(--cream)"><div class="wrap"><span class="eyebrow">Chicago showroom · Local project planning</span><h2>Local support.<br>A clearer path to your kitchen.</h2><div class="grid3"><article class="editorial-card"><h3>Find your service area</h3><p>Explore Chicago-area communities including Naperville, Oak Park, Evanston, Oak Brook and Schaumburg. Confirm delivery and installation availability for your exact address.</p><a class="textlink" href="/locations/">View all 16 communities</a></article><article class="editorial-card"><h3>From ideas to measurements</h3><p>Start with room photos and rough wall lengths. Discuss who verifies site measurements, appliance clearances and cabinet dimensions before approving the design.</p><a class="textlink" href="/services/kitchen-design/">Understand design planning</a></article><article class="editorial-card"><h3>Coordinate installation</h3><p>Choose supply only or discuss installation support. Confirm site readiness, delivery access, responsibilities and the installation schedule with your project team.</p><a class="textlink" href="/services/kitchen-cabinets-installation/">Plan the installation</a></article></div><div class="local-story-teaser"><img src="/assets/finish-natural-oak-room-v2.png" alt="Fictional Naperville family kitchen design" loading="lazy"><div><span class="eyebrow">Nearby-home inspiration</span><h3>A family kitchen in Naperville</h3><p>Explore a sample brief, material selections and before-and-after design comparison. This is a fictional mock-up; verified nearby projects and customer photography are not yet available.</p><a class="textlink" href="/locations/naperville/">Explore the sample case study</a></div></div></div></section>`;}

page('/kitchen-survey/','Find Your Kitchen Starting Point',`${head('A thoughtful first step','What would you love<br>about your next kitchen?','Answer a few project questions and add your email. Get a starting point, share your interests with our team, or continue into a cabinet request.')}<section class="wrap survey-shell"><form id="kitchen-survey"><fieldset><legend>1. What are you planning?</legend>${[['Replace cabinets, keep the layout','Refresh my existing kitchen'],['Renovate and change the layout','Renovate and improve the layout'],['New home or addition','A kitchen for a new home or addition'],['Explore options','I’m exploring ideas']].map(([v,l])=>`<label class="survey-option"><input type="radio" name="intent" value="${v}" required><span>${l}</span></label>`).join('')}</fieldset><fieldset><legend>2. Who is the project for?</legend><label class="survey-option"><input type="radio" name="type" value="Homeowner" required checked><span>My home</span></label><label class="survey-option"><input type="radio" name="type" value="Professional"><span>A professional or development project</span></label></fieldset><label class="field"><span>3. Project city or ZIP code *</span><input name="location" maxlength="100" autocomplete="postal-code" required></label><label class="field"><span>4. When would you like to start? *</span><select name="timeline" required><option value="">Choose a timeframe</option>${['As soon as possible','Within 1–3 months','Within 3–6 months','More than 6 months away','Just exploring'].map(v=>`<option>${v}</option>`).join('')}</select></label><label class="field"><span>5. What cabinet budget are you considering? *</span><select name="budget" required><option value="">Choose a starting range</option>${['Under $10,000','$10,000–$20,000','$20,000–$30,000','$30,000 or more','Help me set a budget'].map(v=>`<option>${v}</option>`).join('')}</select><small>Your planning budget, not a price quote. Installation and other project costs are additional unless quoted.</small></label><label class="field"><span>6. Your email address *</span><input name="email" type="email" maxlength="254" autocomplete="email" placeholder="you@example.com" required><small>Included when you choose to share your brief. Nothing is sent automatically.</small></label><details><summary>Would you like the team to contact you? (optional)</summary><label class="field"><span>Your name</span><input name="name" maxlength="100" autocomplete="given-name"></label><label class="survey-option"><input type="checkbox" name="contact" value="yes"><span>I’d like a reply about my kitchen project when I share my brief.</span></label><p class="caption">These details are included only when you choose to share the brief by email. You are not subscribing to marketing emails.</p></details><p id="survey-error" role="alert" class="error" hidden></p><button class="btn" type="submit">See my kitchen starting point</button><p class="caption">Project choices save in this browser. Nothing is sent until you share your brief or order request through your email app.</p></form><aside class="survey-side"><h3>A clearer first step.</h3><p>You don’t need cabinet measurements or a finished plan.</p><ol><li>Tell us what you’re thinking about.</li><li>See a suggested starting point.</li><li>Explore cabinets and accessories, or share your brief for a conversation.</li></ol><a class="textlink" href="/privacy/">How your information is used</a></aside><section id="survey-result" hidden class="survey-result" aria-live="polite"></section></section>`,'Kitchen project survey for homeowners and professionals: project goals, location, timeline and cabinet budget.');
page('/start-order/','Start Your Cabinet Order',`${head('A thoughtful first step','Your kitchen.<br>Your choices.','Choose your kitchen, accessories and finishes, then select design or installation support. Choose your kitchen, pick cabinets and finishes, then review your request.')}<div class="wrap plan-shell"><section><div class="progress" aria-label="Planning progress"></div><span class="eyebrow" id="plan-step-label">Step 1 of 4</span><div id="plan-step"></div><p id="plan-error" class="error" role="alert" hidden></p><div class="plan-nav"><button class="btn outline" id="plan-back">Back</button><button class="btn" id="plan-next">Continue</button></div></section><aside class="plan-summary"><h3>Your choices</h3><section class="summary-estimate" id="live-estimate" aria-label="Current estimated cabinetry budget" aria-live="polite"></section><dl id="plan-summary"></dl><button type="button" class="btn outline" id="download-selections" disabled>Download my choices</button><p class="caption">Your selections stay on this device. Review an itemized quote with our team before any purchase.</p><button class="textlink" style="background:none;border-top:0;border-left:0;border-right:0" id="reset-plan">Start a new plan</button></aside></div>`,'Create a cabinet plan with your project type, kitchen size, style, material and installation preferences.','noindex,follow');
page('/privacy/','Privacy',`${head('Your information','Your cabinet plan stays with you.','The planner stores your selections in this browser so you can return to them. It does not send your plan to Amber Leaf.')}<div class="wrap"><article class="content"><h2>Device-local information</h2><p>Saved collection choices and planner details use browser storage. You can remove them using the controls below or your browser’s site-data settings.</p><button class="btn outline" id="clear-local-data">Clear saved plans & favorites</button><h2>Kitchen survey</h2><p>Survey project choices stay in this browser and carry into your cabinet request. Planner contact details are saved on this device with your draft and included in the brief you choose to send by email. No survey response is automatically submitted.</p><h2>Downloaded plans</h2><p>Downloading a quote request creates a file on your device. The Email my quote request button opens your email app with your selections addressed to Amber Leaf. You review and send the message yourself; opening it does not submit the request. Attach only project documents you intend to share.</p><h2>External links</h2><p>The showroom page includes an embedded Google Map. Maps directions and research sources open their own websites. Fonts may be loaded from Google Fonts. Those services have their own privacy policies.</p></article></div>`,'How the Amber Leaf cabinet planner handles saved selections and downloaded plans.','noindex,follow');

fs.copyFileSync('catalog-data.mjs',path.join(out,'catalog-data.js'));
fs.mkdirSync(path.join(out,'assets/products'),{recursive:true});
products.forEach(p=>fs.writeFileSync(path.join(out,'assets/products',p.id+'.svg'),productSvg(p)));
page('/cabinets/','Shop Cabinets',head('Cabinet components','Find the cabinet you need.','Explore cabinet and accessory combinations. Try widths, finishes and door styles to find your starting point.')+catalog());
for(const category of ['base','wall','tall'])page('/cabinets/'+category+'/',category+' Cabinets',head('Shop cabinet components',category.charAt(0).toUpperCase()+category.slice(1)+' cabinets.','Choose a component, then make it yours.')+catalog(category));
products.forEach(p=>page('/cabinets/'+p.id+'/',p.name,head('Illustrative cabinet component',p.name,p.description)+productDetail(p)));
page('/colors-materials/','Colors & Materials',head('Finish your kitchen','Color meets construction.','Compare door finishes and cabinet-box materials separately.')+finishPage());
page('/storage-accessories/','Storage Accessories',head('Storage, considered','A place for everyday life.','Find interior storage and a compatible cabinet planning model.')+storagePage());
page('/how-it-works/','How It Works',head('From idea to kitchen','A clear path forward.','Explore, customize and request an itemized quote.')+howPage());
page('/quote-confirmation/','Your Prepared Quote Request',head('Ready for your review','Your request is prepared.','Nothing has been sent yet. Review your reference and send it through your email app.')+'<div class="wrap section" id="prepared-request"></div>','Review and share your cabinet plan.','noindex,follow');
for(const [oldId,newId] of [['olive-modern','charcoal-gray'],['classic-white','soft-white']]){const url='/chicago-kitchen-cabinets/collections/'+oldId+'/';const target='/chicago-kitchen-cabinets/collections/'+newId+'/';const dir=path.join(out,url);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),'<html lang="en"><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,follow"><meta http-equiv="refresh" content="0;url='+target+'"><link rel="canonical" href="'+origin+target+'"><title>Finish page moved</title></head><body><h1>Explore this finish</h1><a href="'+target+'">Continue to the updated finish page</a></body></html>');}
fs.writeFileSync(path.join(out,'gallery-renderer.js'),fs.readFileSync('gallery-renderer.mjs','utf8').replace('./catalog-data.mjs','./catalog-data.js'));
fs.writeFileSync(path.join(out,'data.js'),`window.AMBER_DATA=${JSON.stringify({collections,cities})};`);
fs.writeFileSync(path.join(out,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${routes.filter(r=>r.robots==='index,follow').map(r=>`<url><loc>${origin}${r.url}</loc></url>`).join('')}</urlset>`);
fs.writeFileSync(path.join(out,'robots.txt'),`User-agent: *\nAllow: /\nSitemap: ${origin}/sitemap.xml\n`);
fs.writeFileSync('routes.json',JSON.stringify(routes,null,2));
console.log(`Created ${routes.length} routes for ${manifest.project_id}.`);
